/**
 * Desktop protocol package (desktop design §9.1).
 * - Generated wire types come from the canonical OpenAPI contract
 *   (openapi-schema.gen.ts, regenerated by `pnpm gen:protocol`).
 * - Runtime validators give key responses real schema checks and degrade
 *   unknown enum values to UNKNOWN instead of misjudging authority.
 * - compatibility.ts holds the Desktop/Service compatibility matrix.
 */
export * from './compatibility';
export * from './validators';
export * from './failureContract';

import type { components, operations } from './openapi-schema.gen';

/** JSON values crossing the desktop boundary, including untrusted payloads. */
export type JsonValue = string | number | boolean | null | JsonObject | JsonValue[];
export interface JsonObject {
  [key: string]: JsonValue;
}

/** Extract the JSON request body from a generated OpenAPI operation. */
export type OperationRequestBody<Operation> = Operation extends { requestBody?: infer RequestBody }
  ? RequestBody extends { content: { 'application/json': infer Body } }
    ? Body
    : never
  : never;

/** Extract the query parameter object from a generated OpenAPI operation. */
export type OperationQuery<Operation> = Operation extends { parameters: infer Parameters }
  ? Parameters extends { query?: infer Query }
    ? Query
    : never
  : never;

type SuccessResponse<Responses> = Responses extends { 200: infer Response }
  ? Response
  : Responses extends { 201: infer Response }
    ? Response
    : Responses extends { 202: infer Response }
      ? Response
      : Responses extends { 204: infer Response }
        ? Response
        : never;

type JsonResponseBody<Response> = Response extends { content: { 'application/json': infer Body } } ? Body : never;

/** Extract the first successful JSON response from a generated operation. */
export type OperationResponse<Operation> = Operation extends { responses: infer Responses }
  ? JsonResponseBody<SuccessResponse<Responses>>
  : never;

