// Settings environment surface (settings design): hand-authored aliases for
// the additive /api/v2/environment/* and /api/v2/model-providers contract —
// these endpoints postdate the imported OpenAPI snapshot and stay in this
// facade until the contract is regenerated.

export type EnvironmentFeatureId =
  | 'SANDBOX' | 'WEBSEARCH' | 'TERMINAL' | 'MCP' | 'SKILLS' | 'MODEL'
  | 'HOST_RUNTIME' | 'AGENT_TOOLS'
  | (string & {});
export type EnvironmentFeatureState =
  'READY' | 'ENABLED_NOT_READY' | 'NOT_ENABLED' | 'NOT_INSTALLED'
  | 'UNKNOWN' | 'UNSUPPORTED';
export type EnvironmentFeatureInstallation =
  'NOT_REQUIRED' | 'INSTALLED' | 'MISSING' | 'UNKNOWN';
export type EnvironmentFeatureCheckStatus = 'PASS' | 'FAIL' | 'WARN' | 'UNKNOWN' | 'CHECKING';
export type EnvironmentFeatureFieldType =
  'BOOLEAN' | 'ENUM' | 'INTEGER' | 'LONG' | 'DECIMAL' | 'TEXT' | 'CSV'
  | 'PATH' | 'ENV_REF' | 'MODEL_REF' | (string & {});

/**
 * One editable field inside a feature card (settings design S02): the
 * service-owned form contract the renderer builds typed inputs from.
 * Sensitive fields echo "(set)" instead of the stored value.
 */
export interface EnvironmentFeatureField {
  key: string;
  label: string;
  type: EnvironmentFeatureFieldType;
  options: string[];
  min?: number | null;
  max?: number | null;
  sensitive: boolean;
  readOnly: boolean;
  required: boolean;
  description?: string | null;
  value?: string | null;
}
export type EnvironmentFeatureActionKind =
  'RECHECK' | 'RESTART_SERVICE' | 'OPEN_URL' | 'COPY_TEXT' | 'OPEN_SURFACE' | 'SHOW_GUIDE';

export interface EnvironmentFeatureCheck {
  code: string;
  label: string;
  status: EnvironmentFeatureCheckStatus;
  detail?: string | null;
  fixHint?: string | null;
}

export interface EnvironmentFeatureAction {
  id: string;
  label: string;
  kind: EnvironmentFeatureActionKind;
  style?: 'PRIMARY' | 'SECONDARY' | 'DANGER' | (string & {});
  url?: string;
  copyText?: string;
  guideSteps?: string[];
  enabled?: boolean;
}

/**
 * One model-visible capability tool on the AGENT_TOOLS card: registry
 * facts plus a service-level availability projection. CONDITIONAL means
 * exposure is assembled per run; GATED means a feature prerequisite is
 * off or unready.
 */
export interface EnvironmentFeatureTool {
  name: string;
  capabilityId: string;
  effect: 'READ' | 'WRITE' | 'DELETE' | 'NETWORK' | (string & {});
  summary?: string | null;
  availability: 'AVAILABLE' | 'CONDITIONAL' | 'GATED' | (string & {});
  availabilityDetail?: string | null;
}

export interface EnvironmentFeatureCard {
  featureId: EnvironmentFeatureId;
  title: string;
  desiredEnabled?: boolean | null;
  /** False when the feature has no enable gate — render no toggle. */
  supportsToggle?: boolean;
  effectiveEnabled: boolean;
  state: EnvironmentFeatureState;
  installation: EnvironmentFeatureInstallation;
  pendingRestart: boolean;
  source?: 'FILE' | 'DATABASE' | 'MIXED' | (string & {});
  applyMode?: 'SERVICE_RESTART' | (string & {});
  detail?: Record<string, string>;
  checks: EnvironmentFeatureCheck[];
  actions: EnvironmentFeatureAction[];
  revision: number;
  updatedAt?: number | null;
  /** Apply contract facts (settings design S04). */
  desiredRevision?: number;
  appliedFingerprint?: string | null;
  applyStatus?: 'APPLIED' | 'PENDING' | 'APPLY_FAILED' | (string & {});
  readinessScope?: string;
  checkedAt?: number | null;
  expiresAt?: number | null;
  configHash?: string | null;
  /** Typed field dictionary entries — the form contract. */
  fields?: EnvironmentFeatureField[];
  /** Persisted entries (key→value; null = tombstone). */
  entries?: Record<string, string | null>;
  /** Model tool catalog — populated only on the AGENT_TOOLS card. */
  tools?: EnvironmentFeatureTool[];
}

export interface EnvironmentFeaturesResponse {
  serviceInstanceId: string;
  generatedAtMillis: number;
  features: EnvironmentFeatureCard[];
}

export interface EnvironmentFeatureUpdateRequest {
  enabled?: boolean;
  entries?: Record<string, string | null>;
  expectedRevision?: number;
}

